@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class ClaimController {

    /** A claim as the screen shows it; the amount and the due fixed on settling (null when none
     *  was) are strings with two decimals; openedBy is null for a claim never opened; stated tells
     *  whether a statement bound the claim, statedDue the due it bound it to, late charge included (null when none);
     *  corrects is the number of the claim a correction corrects (null when it is not one); roundsBy
     *  is the date its live figures round by against the sheet's policy date (its own date, or for a
     *  correction the date of the claim it corrects); dueBy is the date it is due by, fixed when it was
     *  added; log is its status log, oldest first, one line per status it has had; deferredUntil is
     *  the date it was deferred until (null when it never was); proofs is how many proofs were added
     *  to it; splitFrom is the number of the claim it was split off (null when it was not); lockedBy is
     *  the user whose open editor locks it (null when no one's does); lateEntry is whether it was
     *  added while its period was soft-closed; remindedOn is the last day a reminder was written for it
     *  (null when none was); ref is its external reference (null when it has none); tags are its tags,
     *  sorted (empty when it has none); voidReason is the reason it was voided with (null when none
     *  was given); comments are its comments, oldest first, each as <user> on <date>: <text>; batch
     *  is the number of the settle batch that settled it (null when a bulk settle did not); lines are
     *  its lines, oldest first, each as <label> <qty> x <unit> (empty when it has none); waived is
     *  whether a steward waived its late charge; proofsReceipt and proofsPhoto are how many of its
     *  proofs are receipts and photos; held is whether the claim itself is held. */
    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note,
            ClaimStatus status, String number, String settledDue, String openedBy, boolean stated,
            String statedDue, String corrects, LocalDate roundsBy, LocalDate dueBy, List<String> log,
            LocalDate deferredUntil, int proofs, String splitFrom, String lockedBy, boolean lateEntry,
            LocalDate remindedOn, String ref, List<String> tags, String voidReason, List<String> comments,
            Long batch, List<String> lines, boolean waived, int proofsReceipt, int proofsPhoto, boolean held) {
        public static ClaimView of(Claim claim, LocalDate roundsBy, List<String> log, List<String> comments) {
            return of(claim, roundsBy, log, comments, List.of());
        }

        public static ClaimView of(Claim claim, LocalDate roundsBy, List<String> log, List<String> comments,
                List<String> lines) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() != null ? claim.getSettledDue().toPlainString() : null,
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() != null ? claim.getStatedDue().toPlainString() : null,
                    claim.getCorrects(), roundsBy, claim.getDueBy(), log, claim.getDeferredUntil(),
                    claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(), claim.isLateEntry(),
                    claim.getRemindedOn(), claim.getRef(), claim.getTags(),
                    claim.getVoidReason(), comments, claim.getBatch(), lines, claim.isWaived(),
                    claim.getProofsReceipt(), claim.getProofsPhoto(), claim.isHeld());
        }
    }

    /** A claim's fields: an amount with up to two decimals (a negative one is a correction), a date
     *  (blank takes the sheet's today), a note (may be empty) and, for a correction, the number of
     *  the claim it corrects, an external reference (blank: none) and tags, comma separated (blank:
     *  none). */
    public record ClaimRequest(
            @NotNull @Digits(integer = 10, fraction = 2) BigDecimal amount,
            LocalDate date,
            @Size(max = 2000) String note,
            @Size(max = 255) String corrects,
            @Size(max = 255) String ref,
            @Size(max = 2000) String tags) {
